  "Próximo período": { es: "Período siguiente", en: "Next period" },
  "Tipo de agendamento": { es: "Tipo de cita", en: "Appointment type" },
  "Por que está cancelando?": { es: "¿Por qué estás cancelando?", en: "Why are you canceling?" },
  "O paciente pediu para remarcar por telefone": { es: "El paciente pidió reprogramar por teléfono", en: "The patient asked to reschedule by phone" },
