  // tradução — reaproveitado, não duplicado aqui.
  "Chamada em andamento": { es: "Llamada en curso", en: "Call in progress" },
  "Reativar microfone": { es: "Reactivar micrófono", en: "Unmute microphone" },
  "Silenciar microfone": { es: "Silenciar micrófono", en: "Mute microphone" },
