  "para:": { es: "a:", en: "to:" },
  "em outra etiqueta existente:": { es: "en otra etiqueta existente:", en: "into another existing tag:" },
  // `"de"` NÃO entra aqui: a chave já existe mais acima no arquivo (linha ~896),
  // e repeti-la é TS1117 — o `as const` do dicionário reprova chave duplicada.
  "contato(s),": { es: "contacto(s),", en: "contact(s)," },
  "lead(s) e": { es: "lead(s) y", en: "lead(s) and" },
  "conversa(s).": { es: "conversación(es).", en: "conversation(s)." },
  "Atenção:": { es: "Atención:", en: "Heads up:" },
