  "registro(s) e em": { es: "registro(s) y en", en: "record(s) and in" },
  "regra(s) de agente.": { es: "regla(s) de agente.", en: "agent rule(s)." },
  // As frases de recusa do servidor. Três delas não tinham entrada: o argumento
